import sys

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    a = list(map(int, input[ptr:ptr+n]))
    ptr += n

    b = [0] * n
    if n == 0:
        print()
        return

    # Try to assign fingers greedily
    for i in range(n):
        if i == 0:
            b[i] = 1
        else:
            if a[i] > a[i-1]:
                # Need b[i] > b[i-1]
                # Try to find the smallest possible finger > b[i-1]
                found = False
                for f in range(b[i-1]+1, 6):
                    if f <= 5:
                        b[i] = f
                        found = True
                        break
                if not found:
                    print(-1)
                    return
            elif a[i] < a[i-1]:
                # Need b[i] < b[i-1]
                # Try to find the largest possible finger < b[i-1]
                found = False
                for f in range(b[i-1]-1, 0, -1):
                    if f >= 1:
                        b[i] = f
                        found = True
                        break
                if not found:
                    print(-1)
                    return
            else:  # a[i] == a[i-1]
                # Need b[i] != b[i-1]
                # Try to find any finger != b[i-1]
                found = False
                for f in range(1, 6):
                    if f != b[i-1]:
                        b[i] = f
                        found = True
                        break
                if not found:
                    print(-1)
                    return

    # Verify the solution
    valid = True
    for i in range(n-1):
        if a[i] < a[i+1] and b[i] >= b[i+1]:
            valid = False
            break
        if a[i] > a[i+1] and b[i] <= b[i+1]:
            valid = False
            break
        if a[i] == a[i+1] and b[i] == b[i+1]:
            valid = False
            break
    if not valid:
        print(-1)
        return

    print(' '.join(map(str, b)))

solve()
